#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
uniform float2 amzVelocity,amzPivot,amzScale;
uniform float amzAngularVelocity,amzScaleVelocity,amzStartTime,amzEndTime;

struct AC_ImageInfo { int texture; float2 amzLocal_size; };
const float3x3 labPlaneInverse=float3x3(1);
float4x4 amzQuaternion(float4 q) {
    q /= max(length(q),0.000001);
    float x=q.x,y=q.y,z=q.z,w=q.w;
    return float4x4(1-2*(y*y+z*z),2*(x*y+w*z),2*(x*z-w*y),0,
                    2*(x*y-w*z),1-2*(x*x+z*z),2*(y*z+w*x),0,
                    2*(x*z+w*y),2*(y*z-w*x),1-2*(x*x+y*y),0,0,0,0,1);
}
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval(((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0))); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);return float4(0.0); }
float4 amzTexture(int tex,float2 uv,float bias){return amzTexture(tex,uv);}
uniform float amzp_shCyanRed;
uniform float amzp_shMagGreen;
uniform float amzp_shYelBlue;
uniform float amzp_midCyanRed;
uniform float amzp_midMagGreen;
uniform float amzp_midYelBlue;
uniform float amzp_hlCyanRed;
uniform float amzp_hlMagGreen;
uniform float amzp_hlYelBlue;
uniform float amzp_shSatAdjust;
uniform float amzp_shLumAdjust;
uniform float amzp_midSatAdjust;
uniform float amzp_midLumAdjust;
uniform float amzp_hlSatAdjust;
uniform float amzp_hlLumAdjust;
uniform float amzp_masterSaturation;
uniform float amzp_masterBrightness;
uniform float amzp_shBoundary;
uniform float amzp_hlBoundary;
uniform float amzp_preserveLuminance;
uniform float amzp_globalMix;
    float lum(float3 c) {
        return dot(c, float3(0.2126, 0.7152, 0.0722));
    }
    float3 balanceCMYRGB(float3 rgb, float cr, float mg, float yb, float zoneMask) {
        if (abs(cr) < 0.5 && abs(mg) < 0.5 && abs(yb) < 0.5) return rgb;
        float crN = cr / 100.0;
        float mgN = mg / 100.0;
        float ybN = yb / 100.0;
        crN *= zoneMask;
        mgN *= zoneMask;
        ybN *= zoneMask;
        float rShift = crN * 0.1;
        float gShift = -crN * 0.05;
        float bShift = -crN * 0.05;
        gShift += mgN * 0.1;
        rShift -= mgN * 0.05;
        bShift -= mgN * 0.03;
        bShift += ybN * 0.1;
        rShift -= ybN * 0.03;
        gShift -= ybN * 0.05;
        rgb.r += rShift;
        rgb.g += gShift;
        rgb.b += bShift;
        return rgb;
    }
    float3 adjustSaturation(float3 rgb, float amount, float zoneMask) {
        if (abs(amount) < 0.5) return rgb;
        float a = amount / 100.0 * zoneMask;
        float l = lum(rgb);
        return mix(float3(l), rgb, 1.0 + a);
    }
    float3 adjustBrightness(float3 rgb, float amount, float zoneMask) {
        if (abs(amount) < 0.5) return rgb;
        float a = amount / 100.0 * 0.3 * zoneMask;
        float l = lum(rgb);
        float origL = max(l, 0.00001);
        float newL = max(l + a, 0.0);
        return rgb * (newL / origL);
    }
    void amzRender() {
        float2 uv = amzScreenNorm();
        float4 original = amzTexture(0, uv);
        float3 rgb = max(original.rgb, 0.0);
        float3 baseRGB = rgb;
        float l = lum(rgb);
        float origLum = l;
        float shMask = 1.0 - smoothstep(max(amzp_shBoundary - 0.15, 0.0), amzp_shBoundary + 0.05, l);
        float hlMask = smoothstep(amzp_hlBoundary - 0.05, min(amzp_hlBoundary + 0.15, 1.0), l);
        float midMask = 1.0 - shMask - hlMask;
        midMask = max(midMask, 0.0);
        float totalMask = shMask + midMask + hlMask;
        if (totalMask > 0.00001) {
            shMask /= totalMask;
            midMask /= totalMask;
            hlMask /= totalMask;
        }
        float3 shResult = balanceCMYRGB(rgb, amzp_shCyanRed, amzp_shMagGreen, amzp_shYelBlue, 1.0);
        shResult = adjustSaturation(shResult, amzp_shSatAdjust, 1.0);
        shResult = adjustBrightness(shResult, amzp_shLumAdjust, 1.0);
        float3 midResult = balanceCMYRGB(rgb, amzp_midCyanRed, amzp_midMagGreen, amzp_midYelBlue, 1.0);
        midResult = adjustSaturation(midResult, amzp_midSatAdjust, 1.0);
        midResult = adjustBrightness(midResult, amzp_midLumAdjust, 1.0);
        float3 hlResult = balanceCMYRGB(rgb, amzp_hlCyanRed, amzp_hlMagGreen, amzp_hlYelBlue, 1.0);
        hlResult = adjustSaturation(hlResult, amzp_hlSatAdjust, 1.0);
        hlResult = adjustBrightness(hlResult, amzp_hlLumAdjust, 1.0);
        float3 result = shResult * shMask
                    + midResult * midMask
                    + hlResult * hlMask;
        if (abs(amzp_masterSaturation - 100.0) > 0.5) {
            float ml = lum(result);
            result = mix(float3(ml), result, amzp_masterSaturation / 100.0);
        }
        if (abs(amzp_masterBrightness) > 0.5) {
            float mb = amzp_masterBrightness / 100.0 * 0.3;
            float rl = lum(result);
            float origRL = max(rl, 0.00001);
            float newRL = max(rl + mb, 0.0);
            result *= newRL / origRL;
        }
        if ((amzp_preserveLuminance>0.5)) {
            float newLum = lum(result);
            if (newLum > 0.00001) {
                result *= origLum / newLum;
            }
        }
        result = mix(baseRGB, result, amzp_globalMix);
        result = clamp(result, 0.0, 1.0);
        amzOutput = float4(result, original.a);
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }

